def format_guide(g):
    slug, title, desc, cat, diff, time, steps, faqs = g
    steps_str = ", ".join(f'{{ title: "{s[0]}", description: "{s[1]}" }}' for s in steps)
    faq_str = ", ".join(f'{{ question: "{q}", answer: "{a}" }}' for q, a in faqs)
    desc = desc.replace('"', '\\"')
    return (
        f'  {{ slug: "{slug}", title: "{title}", '
        f'description: "{desc}", '
        f'category: "{cat}", '
        f'difficulty: "{diff}", '
        f'timeToRead: "{time}", '
        f'steps: [{steps_str}], '
        f'faq: [{faq_str}] }},'
    )

lines = ['import type { Guide } from "@/types";', '', 'export const guides: Guide[] = [']
for g in GUIDES:
    lines.append(format_guide(g))
lines.append('];')
lines.append('')

content = '\n'.join(lines)
with open('/Users/adda247/personal/shipsquad/shipsquad-front/src/data/guides.ts', 'w') as f:
    f.write(content)
print(f"Written {len(GUIDES)} guides to guides.ts ({len(content)} bytes)")
